-- =========================================================
-- 排球隊管理系統 Supabase 資料庫初始化語法 (setup.sql)
-- 請複製以下全部內容，貼上至 Supabase SQL Editor 並點擊 Run：
-- https://supabase.com/dashboard/project/mtorunczoyjvhmufaast/sql/new
-- =========================================================

-- 1. 帳號與排球隊成員資料表 (team_users)
CREATE TABLE IF NOT EXISTS public.team_users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    name TEXT NOT NULL,
    jersey_number TEXT DEFAULT '',
    role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('admin', 'member')),
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. 排球隊體能紀錄表 (team_fitness - 管理者指派，預設未完成)
CREATE TABLE IF NOT EXISTS public.team_fitness (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.team_users(id) ON DELETE CASCADE,
    user_name TEXT NOT NULL,
    task_name TEXT NOT NULL,
    target_date DATE NOT NULL DEFAULT CURRENT_DATE,
    is_completed BOOLEAN NOT NULL DEFAULT false,
    note TEXT DEFAULT '',
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 3. 隊費與代繳費用表 (team_fees)
CREATE TABLE IF NOT EXISTS public.team_fees (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.team_users(id) ON DELETE CASCADE,
    user_name TEXT NOT NULL,
    fee_type TEXT NOT NULL DEFAULT '隊費' CHECK (fee_type IN ('隊費', '代繳費用')),
    title TEXT NOT NULL,
    amount INTEGER NOT NULL DEFAULT 0,
    due_date DATE DEFAULT CURRENT_DATE,
    is_paid BOOLEAN NOT NULL DEFAULT false,
    payment_note TEXT DEFAULT '',
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 4. 請假紀錄表 (team_leaves - 含請假照片、補體能連結/文字、補體能照片)
CREATE TABLE IF NOT EXISTS public.team_leaves (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.team_users(id) ON DELETE CASCADE,
    user_name TEXT NOT NULL,
    leave_date DATE NOT NULL DEFAULT CURRENT_DATE,
    leave_type TEXT NOT NULL DEFAULT '事假',
    session_name TEXT NOT NULL DEFAULT '例行練球',
    reason TEXT DEFAULT '',
    leave_photo TEXT DEFAULT '',
    makeup_text TEXT DEFAULT '',
    makeup_photo TEXT DEFAULT '',
    makeup_done BOOLEAN NOT NULL DEFAULT false,
    status TEXT NOT NULL DEFAULT '待審核' CHECK (status IN ('待審核', '已核准', '已駁回')),
    created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.team_leaves ADD COLUMN IF NOT EXISTS leave_photo TEXT DEFAULT '';
ALTER TABLE public.team_leaves ADD COLUMN IF NOT EXISTS makeup_text TEXT DEFAULT '';
ALTER TABLE public.team_leaves ADD COLUMN IF NOT EXISTS makeup_photo TEXT DEFAULT '';
ALTER TABLE public.team_leaves ADD COLUMN IF NOT EXISTS makeup_done BOOLEAN NOT NULL DEFAULT false;

-- 5. 球隊經費收支表 (team_finances)
CREATE TABLE IF NOT EXISTS public.team_finances (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tx_date DATE NOT NULL DEFAULT CURRENT_DATE,
    tx_type TEXT NOT NULL DEFAULT '支出' CHECK (tx_type IN ('收入', '支出')),
    category TEXT NOT NULL DEFAULT '器材採購',
    title TEXT NOT NULL,
    amount INTEGER NOT NULL DEFAULT 0,
    handler TEXT DEFAULT '',
    note TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT now()
);

-- =========================================================
-- 開放 RLS 權限供前端 API (anon key) 即時讀寫
-- =========================================================
ALTER TABLE public.team_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_fitness ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_fees ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_leaves ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_finances ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "allow_all_team_users" ON public.team_users;
CREATE POLICY "allow_all_team_users" ON public.team_users FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "allow_all_team_fitness" ON public.team_fitness;
CREATE POLICY "allow_all_team_fitness" ON public.team_fitness FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "allow_all_team_fees" ON public.team_fees;
CREATE POLICY "allow_all_team_fees" ON public.team_fees FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "allow_all_team_leaves" ON public.team_leaves;
CREATE POLICY "allow_all_team_leaves" ON public.team_leaves FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "allow_all_team_finances" ON public.team_finances;
CREATE POLICY "allow_all_team_finances" ON public.team_finances FOR ALL USING (true) WITH CHECK (true);

-- =========================================================
-- 啟用 Supabase Realtime 即時同步廣播
-- =========================================================
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'team_users') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.team_users;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'team_fitness') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.team_fitness;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'team_fees') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.team_fees;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'team_leaves') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.team_leaves;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'team_finances') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.team_finances;
    END IF;
END $$;

