DELETE FROM public.team_users WHERE username IN ('admin', 'player1', 'player2', 'player3');

ON CONFLICT (username) DO UPDATE SET
    password = EXCLUDED.password,
    name = EXCLUDED.name,
    role = EXCLUDED.role;

